// Typed MyGo bindings (regenerated by `mygo generate` during `mygo build`).
import { call } from "mygo-runtime";

export interface AppSettings {
  scheme: string;
  mixedInput: boolean;
  chinesePunctuation: boolean;
  skin: string;
  themeMode: string;
  darkMode: boolean;
  systemDark: boolean;
  firstCandidateSize: number;
  keyOpacity: number;
  typingGlow: boolean;
  keyLetterSize: number;
  keyLetterBold: boolean;
}

export const SettingsService = {
  load(): Promise<AppSettings> {
    return call("SettingsService.Load");
  },
  save(s: AppSettings): Promise<AppSettings> {
    return call("SettingsService.Save", s);
  },
  reset(): Promise<AppSettings> {
    return call("SettingsService.Reset");
  },
  close(): Promise<void> {
    return call("SettingsService.Close");
  },
};
